import{_ as e}from"./chunks/overview.DGkNQtk6.js";import{_ as o,o as a,c as r,a2 as n}from"./chunks/framework.CS-cBh1g.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),s={name:"guide/introduction.md"};function d(i,t,h,c,l,u){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Mayhem is one desktop app for a robot&#39;s software. You build pose-based autos, watch state machines run, analyze match logs, see what code is on the robot, and review what a code change actually does before it goes on the robot, whether a coding agent or a teammate wrote it.</p><p><img src="'+e+'" alt="Mayhem&#39;s Overview workspace"></p><h2 id="how-the-pieces-fit" tabindex="-1">How the pieces fit <a class="header-anchor" href="#how-the-pieces-fit" aria-label="Permalink to &quot;How the pieces fit&quot;">​</a></h2><p>Mayhem works on the robot code repository you already have. It doesn&#39;t replace your code; it reads it and adds a few files next to it.</p><table tabindex="0"><thead><tr><th>Piece</th><th>Where it lives</th><th>What it does</th></tr></thead><tbody><tr><td><strong>The desktop app</strong></td><td>Your laptop</td><td>Every workspace in this guide.</td></tr><tr><td><strong><code>robot.mayhem.json</code></strong></td><td>Root of the robot repo</td><td>The project: robot limits, autonomous routines and state machines. The app edits it; agents can too.</td></tr><tr><td><strong><code>tools/mayhem/</code></strong></td><td>Robot repo</td><td>Driver-control machines, sim proof scenarios and the robot explainer. See <a href="/Mayhem/reference/repo-files">the tools/mayhem folder</a>.</td></tr><tr><td><strong>The C++ library</strong></td><td>Robot code (<code>MayhemCpp</code> vendordep)</td><td>Runs the exported routines and state machines on the robot. See <a href="/Mayhem/robot-code/setup">Robot code</a>.</td></tr><tr><td><strong><code>MayhemProject.h</code></strong></td><td>Robot code, generated</td><td>Your routines and machines as C++, exported from the project.</td></tr><tr><td><strong>Agents (optional)</strong></td><td>Your laptop</td><td>Coding agents change the code on a branch; you review each branch in Changes. See <a href="/Mayhem/agents/">Agents</a>.</td></tr></tbody></table><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose your path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to</th><th>Start here</th></tr></thead><tbody><tr><td>Install the app</td><td><a href="/Mayhem/guide/installation">Installation</a></td></tr><tr><td>Build and preview an auto</td><td><a href="/Mayhem/guide/quick-start">Your first auto</a></td></tr><tr><td>See how a team uses it week to week</td><td><a href="/Mayhem/guide/workflow">A week with Mayhem</a></td></tr><tr><td>Find your way around the app</td><td><a href="/Mayhem/suite/overview">The app at a glance</a></td></tr><tr><td>Get autos and state machines running on the robot</td><td><a href="/Mayhem/robot-code/setup">Set up a robot repo</a></td></tr><tr><td>Review a robot code change</td><td><a href="/Mayhem/suite/changes">Changes</a></td></tr><tr><td>Work with coding agents</td><td><a href="/Mayhem/agents/">Connect an agent</a></td></tr><tr><td>Work on Mayhem itself</td><td><a href="/Mayhem/reference/building">Building and contributing</a></td></tr></tbody></table><h2 id="the-workspaces" tabindex="-1">The workspaces <a class="header-anchor" href="#the-workspaces" aria-label="Permalink to &quot;The workspaces&quot;">​</a></h2><ul><li><strong><a href="/Mayhem/suite/overview">Overview</a>:</strong> changes waiting for review, routine thumbnails, latest logs, the match-ready checklist and a clickable map of how the robot works.</li><li><strong><a href="/Mayhem/suite/changes">Changes</a>:</strong> the branches waiting for review, and what each one does to controls, state machines, values, hardware and autos, with a before/after sim proof.</li><li><strong><a href="/Mayhem/suite/autonomous">Autonomous</a>:</strong> place goals, add actions and conditions, preview the path or the full routine.</li><li><strong><a href="/Mayhem/suite/state-machines">State machines</a>:</strong> graphs in simulation, live over NT4, or replayed from a log.</li><li><strong><a href="/Mayhem/suite/logs">Logs</a>:</strong> findings, power, signals and pose replay for every recording.</li><li><strong><a href="/Mayhem/suite/robot">Robot</a>:</strong> what&#39;s on the robot now, every value in the code, specs, connection and log collection.</li></ul><div class="warning custom-block"><p class="custom-block-title">What the preview doesn&#39;t prove</p><p>The auto preview is kinematic. It doesn&#39;t run your custom robot code, model traction or avoid obstacles, and the pose controller still has to be tuned on the real robot. See the <a href="https://github.com/ryanabraham1/Mayhem/blob/main/docs/SUITE_STATUS.md" target="_blank" rel="noreferrer">implementation status</a> for what&#39;s been verified.</p></div>',11)])])}const b=o(s,[["render",d]]);export{g as __pageData,b as default};
